import { Agent, routeAgentRequest } from 'agents';
import { generateText } from 'ai';
import { createWorkersAI } from 'workers-ai-provider';

const MODEL = '@cf/meta/llama-3.3-70b-instruct-fp8-fast';

export class Chat extends Agent {
  async onMessage(connection, message) {
    const prompt = typeof message === 'string' ? message : new TextDecoder().decode(message);
    const workersai = createWorkersAI({ binding: this.env.AI });

    try {
      const { text } = await generateText({ model: workersai(MODEL), prompt });
      connection.send(text);
    } catch (err) {
      console.error('generateText failed', err);
      connection.send('Sorry, something went wrong generating a response.');
    }
  }
}

export default {
  async fetch(request, env) {
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

